// Rule L3b: a function that returns nothing, called as a value: the value is its first `out`.
/// @asset Path(Game, "Functions/MF_MgOnlyOuts")
extern void MF_MgOnlyOuts(float3 Colour, out float3 Tinted, out float Weight);

/// @name DreamShaderTests/Migrate/M_MgVoidValue
export void M_MgVoidValue(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float3 MF_MgOnlyOuts_Tinted;
    float MF_MgOnlyOuts_Weight;
    MF_MgOnlyOuts(float3(1.0, 0.5, 0.25), Tinted = MF_MgOnlyOuts_Tinted, Weight = MF_MgOnlyOuts_Weight);
    Color = MF_MgOnlyOuts_Tinted + float3(0.1, 0.1, 0.1);
    Base.EmissiveColor = Color;
}
